<?php

namespace MongoDB\BSON;

/**
 * <div id="class.mongodb-bson-unserializable" class="reference"> <h1 class="title">The MongoDB\BSON\Unserializable interface</h1>  <div class="partintro"><p class="verinfo">(mongodb &gt;=1.0.0)</p>  <div class="section" id="mongodb-bson-unserializable.intro">   <h2 class="title">简介</h2>   <p class="simpara">    Classes that implement this interface may be specified in a    <a href="https://php.net/manual/zh/mongodb.persistence.php#mongodb.persistence.typemaps" class="link">type map</a> for    unserializing BSON arrays and documents (both root and embedded).   </p>  </div>  <div class="section" id="mongodb-bson-unserializable.synopsis">   <h2 class="title">接口摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">MongoDB\BSON\Unserializable</strong>     </span>     {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-bson-unserializable.bsonunserialize.php" class="methodname" style="color:#CC7832">bsonUnserialize</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">\$data</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>   }</div>  </div>  <div class="section">   <h2 class="title">更新日志</h2>   <table class="doctable informaltable">         <thead>      <tr>       <th>版本</th>       <th>说明</th>      </tr>     </thead>     <tbody class="tbody">             <tr>        <td>PECL mongodb 2.0.0</td>        <td>         之前声明为暂定的返回类型现在已被强制执行。        </td>       </tr>             <tr>        <td>PECL mongodb 1.15.0</td>        <td>         在 PHP 8.0 及更高版本中，方法的返回类型被声明为暂定（tentative），         这会导致在实现该接口但未声明相应返回类型的代码中触发弃用提示。         可以添加 <span class="code">#[ReturnTypeWillChange]</span> 属性来消除该弃用提示。        </td>       </tr>     </tbody>       </table>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link MongoDB\BSON\Unserializable::bsonUnserialize} — Constructs the object from a BSON array or document</li></ul></div>
 * 
 * Classes that implement this interface may be specified in a type map for unserializing BSON arrays and documents (both root and embedded).
 * @link https://php.net/manual/zh/class.mongodb-bson-unserializable.php
 */
interface Unserializable extends Type
{
    /**
 * <div id="mongodb-bson-unserializable.bsonunserialize" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\Unserializable::bsonUnserialize</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\Unserializable::bsonUnserialize</span> — <span class="dc-title">Constructs the object from a BSON array or document</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-unserializable.bsonunserialize-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\Unserializable::bsonUnserialize</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">\$data</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   Called during unserialization of the object from BSON. The properties of the   BSON array or document will be passed to the method as an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>.  </p>  <p class="simpara">   Remember to check for an <span class="property">_id</span> property when handling data   from a BSON document.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    This method acts as the    <a href="https://php.net/manual/zh/language.oop5.decon.php#language.oop5.decon.constructor" class="link">constructor</a> of the    object. The <a href="https://php.net/manual/zh/language.oop5.decon.php#object.construct" class="link">__construct()</a> method    will <em>not</em> be called after this method.   </span>  </p></blockquote> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-unserializable.bsonunserialize-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">data</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>)</dt>    <dd>     <span class="simpara">      Properties within the BSON array or document.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-bson-unserializable.bsonunserialize-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   The return value from this method is ignored.  </p> </div> <div class="refsect1 changelog" id="refsect1-mongodb-bson-unserializable.bsonunserialize-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">            <tr>        <td>PECL mongodb 2.0.0</td>        <td>         之前声明为暂定的返回类型现在已被强制执行。        </td>       </tr>    </tbody>     </table> </div> <div class="refsect1 examples" id="refsect1-mongodb-bson-unserializable.bsonunserialize-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\BSON\Unserializable::bsonUnserialize()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br></span><span style="color: #007700">class </span><span style="color: #9876AA">MyDocument </span><span style="color: #007700">implements </span><span style="color: #9876AA">MongoDB\BSON\Unserializable<br></span><span style="color: #007700">{<br>    private </span><span style="color: #9876AA">\$data </span><span style="color: #007700">= [];<br><br>    function </span><span style="color: #9876AA">bsonUnserialize</span><span style="color: #007700">(array </span><span style="color: #9876AA">\$data</span><span style="color: #007700">): </span><span style="color: #9876AA">void<br>    </span><span style="color: #007700">{<br>        </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">data </span><span style="color: #007700">= </span><span style="color: #9876AA">\$data</span><span style="color: #007700">;<br>    }<br>}<br><br></span><span style="color: #9876AA">\$bson </span><span style="color: #007700">= </span><span style="color: #9876AA">MongoDB\BSON\Document</span><span style="color: #007700">::</span><span style="color: #9876AA">fromJSON</span><span style="color: #007700">(</span><span style="color: #DD0000">'{ "foo": "bar" }'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$bson</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">toPHP</span><span style="color: #007700">([</span><span style="color: #DD0000">'root' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'MyDocument'</span><span style="color: #007700">]));<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(MyDocument)#1&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;["data":"MyDocument":private]=&gt;<br>&nbsp;&nbsp;array(1)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["foo"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(3)&nbsp;"bar"<br>&nbsp;&nbsp;}<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-unserializable.bsonunserialize-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link MongoDB\BSON\Serializable::bsonSerialize()} - Provides an array or document to serialize as BSON</span></li>   <li><span class="interfacename"><a href="https://php.net/manual/zh/class.mongodb-bson-persistable.php" class="interfacename">MongoDB\BSON\Persistable</a></span></li>   <li><a href="https://php.net/manual/zh/mongodb.persistence.php" class="xref">Persisting Data</a></li>  </ul> </div></div>
 * 
     * Constructs the object from a BSON array or document
     * Called during unserialization of the object from BSON.
     * The properties of the BSON array or document will be passed to the method as an array.
     * @link https://php.net/manual/zh/mongodb-bson-unserializable.bsonunserialize.php
     * @param array $data Properties within the BSON array or document.
     */
    public function bsonUnserialize(array $data): void;
}
